# patch_20260917b_ai_reply_only.ps1  (v2: fixes 'Del' name clash with the built-in del alias)
# AI is used ONLY by the "Generate AI reply" button (OpenAI). Everything else is removed:
# - inbound mail: rule-based classification only (no AI, no automatic drafts)
# - deleted: claude-client, cost-tracker, prompt-renderer, consultation-worker,
#   task "AI decompose", "Generate AI email" (new mail), simulate-inbound
# - external_data is merged (ingest headers are no longer erased)
# Safe + idempotent: each file is changed only if it matches GitHub commit be2b2dc
# (or an earlier rule_classifier patch). Already done -> SKIP. Local edits -> WARN, untouched.
# ASCII only. PS 5.x compatible.
$ErrorActionPreference = 'Stop'
$repo = 'C:\dev\mbg-project'
$utf8 = New-Object System.Text.UTF8Encoding($false)
$sha = [System.Security.Cryptography.SHA256]::Create()
function HashOf([byte[]]$b) { return (($sha.ComputeHash($b) | ForEach-Object { $_.ToString('x2') }) -join '') }
function LocalHash([string]$p) {
  $b = [System.IO.File]::ReadAllBytes($p)
  if ($b.Length -ge 3 -and $b[0] -eq 0xEF -and $b[1] -eq 0xBB -and $b[2] -eq 0xBF) { $b = $b[3..($b.Length-1)] }
  $s = $utf8.GetString($b) -replace "`r`n", "`n"
  return (HashOf ($utf8.GetBytes($s)))
}
$ok = 0; $skip = 0; $warn = 0
function Put([string]$rel, [string]$oldHash, [string]$newHash, [string]$b64) {
  $p = [System.IO.Path]::Combine($script:repo, $rel)
  $bytes = [Convert]::FromBase64String($b64)
  if ([System.IO.File]::Exists($p)) {
    $cur = LocalHash $p
    if ($cur -eq $newHash) { Write-Host "[SKIP] $rel (already applied)"; $script:skip++; return }
    if (-not (($oldHash -split '\|') -contains $cur)) { Write-Host "[WARN] $rel differs from GitHub version - NOT changed"; $script:warn++; return }
  } elseif (-not (($oldHash -split '\|') -contains 'NEW')) {
    Write-Host "[WARN] $rel not found - NOT changed"; $script:warn++; return
  }
  [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($p)) | Out-Null
  [System.IO.File]::WriteAllBytes($p, $bytes)
  Write-Host "[OK]   $rel"; $script:ok++
}
function Remove-RepoFile([string]$rel, [string]$oldHash) {
  $p = [System.IO.Path]::Combine($script:repo, $rel)
  if (-not [System.IO.File]::Exists($p)) { Write-Host "[SKIP] $rel (already deleted)"; $script:skip++; return }
  $cur = LocalHash $p
  if (-not (($oldHash -split '\|') -contains $cur)) { Write-Host "[WARN] $rel differs from GitHub version - NOT deleted"; $script:warn++; return }
  [System.IO.File]::Delete($p)
  Write-Host "[DEL]  $rel"; $script:ok++
}
if (-not (Test-Path -LiteralPath $repo)) { Write-Host "ERROR repo not found: $repo"; return }
$head = $null; try { $head = [string](& git -C $repo rev-parse HEAD 2>$null) } catch { $head = $null }
if ($head -and -not $head.StartsWith('be2b2dc')) { Write-Host ('NOTE: local HEAD is ' + $head.Substring(0,7) + ', expected be2b2dc (origin/marinebiogroup).') }

